const fs = require("node:fs");
const path = require("node:path");
const { readProduct } = require("./reader-source.cjs");
const { readTakealotSeller } = require("../collector/takealot-seller.cjs");
const root = __dirname;
fs.writeFileSync(
  path.join(root, "reader.mjs"),
  "// Generated by node extension/build.cjs. Edit reader-source.cjs, not this file.\nexport " +
    readProduct
      .toString()
      .replace("/* SELLER_READER */", readTakealotSeller.toString()) +
    "\n",
);
const stores = JSON.parse(
  fs.readFileSync(path.join(root, "../data/stores.json")),
).filter((s) => s.status === "tracked");
const hosts = stores.map((s) => new URL(s.home_url).origin + "/*");
const manifest = {
  manifest_version: 3,
  name: "Trust Me Bru",
  version: "0.1.0",
  minimum_chrome_version: "120",
  description:
    "The price claim, the dated evidence, and a slow local price collector.",
  permissions: ["storage", "alarms", "scripting"],
  host_permissions: [
    ...hosts,
    "http://127.0.0.1:3210/*",
    "http://localhost:3210/*",
  ],
  background: { service_worker: "background.mjs", type: "module" },
  action: { default_popup: "popup.html", default_title: "Trust Me Bru" },
  content_scripts: [
    { matches: hosts, js: ["content.js"], run_at: "document_idle" },
  ],
  web_accessible_resources: [
    { resources: ["assets/mono.woff2"], matches: hosts },
  ],
  content_security_policy: {
    extension_pages: "script-src 'self'; object-src 'none'",
  },
};
fs.writeFileSync(
  path.join(root, "manifest.json"),
  JSON.stringify(manifest, null, 2) + "\n",
);
fs.copyFileSync(
  path.join(
    root,
    "../site/node_modules/@fontsource/ibm-plex-mono/files/ibm-plex-mono-latin-400-normal.woff2",
  ),
  path.join(root, "assets/mono.woff2"),
);
fs.copyFileSync(
  path.join(root, "../site/node_modules/@fontsource/ibm-plex-mono/LICENSE"),
  path.join(root, "assets/FONT-LICENSE"),
);
